import { ocrFailed, validation, type StructuredError } from './errors.js';

// ---------------------------------------------------------------------------
// C6: model constraint
// ---------------------------------------------------------------------------

/**
 * gemini_ocr is HARD-PINNED to gemini-2.5-flash and must never be pointed at
 * a Pro model. Rationale (C6): thinkingBudget: 0 is required to keep OCR
 * calls fast/cheap and deterministic-ish (no chain-of-thought variance in a
 * pure transcription task) — gemini-2.5-flash supports thinkingBudget: 0,
 * but gemini-2.5-pro's minimum is 128 and refuses 0. Using Pro here would
 * silently reintroduce a nonzero thinking budget (cost + latency + a source
 * of non-determinism we don't want for OCR) contrary to the tool's design.
 */
export const OCR_MODEL = 'gemini-2.5-flash' as const;

/** thinkingBudget: 0 — Flash-only. See OCR_MODEL doc for why Pro is barred. */
export const OCR_THINKING_BUDGET = 0;

export function assertOcrModelAllowed(model: string): void {
  if (model !== OCR_MODEL) {
    throw validation(
      `gemini_ocr only supports ${OCR_MODEL} (thinkingBudget:0 requires Flash; ` +
        `gemini-2.5-pro's minimum thinking budget is 128 and would silently ` +
        `change OCR behavior). Got "${model}".`,
    ) as unknown as Error;
  }
}

// ---------------------------------------------------------------------------
// Part ordering for vision calls
// ---------------------------------------------------------------------------

export interface InlineImagePart {
  inlineData: { mimeType: string; data: string };
}
/** Files-API-referenced image part — used instead of InlineImagePart once a
 * page's image has been uploaded via uploadViaFilesApi() below. */
export interface FileDataImagePart {
  fileData: { mimeType: string; fileUri: string };
}
export type ImagePart = InlineImagePart | FileDataImagePart;
export interface TextPart {
  text: string;
}
export type ContentPart = ImagePart | TextPart;

/**
 * Per C6: for vision OCR calls, IMAGE parts must precede the TEXT/prompt
 * part in the `contents` array. This is the OPPOSITE convention from
 * write_section.ts and friends, which send a single text `user` string
 * (there's nothing to order — no images). Gemini's multimodal grounding is
 * more reliable when the model sees the visual evidence before being told
 * what to do with it, which matters for OCR specifically (vs. e.g. a
 * text-editing task where the instruction naturally comes first).
 *
 * Accepts either inline (base64) or Files-API (fileUri) image parts —
 * ordering is the only constraint this function enforces, not payload shape.
 */
export function buildOcrParts(images: ImagePart[], promptText: string): ContentPart[] {
  return [...images, { text: promptText }];
}

// ---------------------------------------------------------------------------
// Inline vs Files API payload-size decision
// ---------------------------------------------------------------------------

/**
 * Gemini's inline (base64-in-request) payload limit is documented around
 * 20MB for the total request. Base64 inflates raw bytes by ~4/3, so we
 * estimate against the RAW (pre-base64) byte size and apply the same 20MB
 * threshold as the task's stated cap, treating it as "combined inline
 * payload" (i.e. already accounting for the encoding overhead implicitly by
 * being conservative — see INLINE_SIZE_LIMIT_BYTES comment).
 */
export const INLINE_SIZE_LIMIT_BYTES = 20 * 1024 * 1024; // 20MB

export interface PayloadDecision {
  useFilesApi: boolean;
  estimatedBase64Bytes: number;
}

/**
 * Decide whether a batch of page images should be sent inline or via the
 * Files API, based on estimated total payload size.
 *
 * @param rawImageByteSizes raw (pre-base64) byte length of each page PNG in
 *   the batch.
 */
export function decideUploadPath(rawImageByteSizes: number[]): PayloadDecision {
  const totalRawBytes = rawImageByteSizes.reduce((a, b) => a + b, 0);
  // Base64 encoding inflates size by ~4/3 (33%); JSON envelope overhead is
  // comparatively negligible for image-heavy payloads, so we fold it into
  // this single multiplier rather than modeling it separately.
  const estimatedBase64Bytes = Math.ceil(totalRawBytes * (4 / 3));
  return {
    useFilesApi: estimatedBase64Bytes > INLINE_SIZE_LIMIT_BYTES,
    estimatedBase64Bytes,
  };
}

// ---------------------------------------------------------------------------
// Files API upload + poll-until-ACTIVE
// ---------------------------------------------------------------------------

/**
 * Poll interval while an uploaded file's state is PROCESSING. 2s balances
 * responsiveness against not hammering the Files API `get` endpoint;
 * comfortably inside the 1-3s range the task called out as reasonable.
 */
export const FILES_API_POLL_INTERVAL_MS = 2000;

/**
 * Total time budget for a single upload to leave PROCESSING and reach
 * ACTIVE. 2 minutes: generous headroom over typical large-PDF-page-image
 * processing times (usually seconds) while still failing fast (well under
 * a Claude Code tool-call timeout) instead of hanging indefinitely if the
 * Files API stalls.
 */
export const FILES_API_POLL_TIMEOUT_MS = 120_000;

export interface UploadedFileRef {
  /** Resource id (e.g. "files/abc123") — pass to get()/delete(). */
  name: string;
  /** URI to reference in a generateContent `fileData` part. */
  uri: string;
  mimeType: string;
}

/** Minimal shape of a Files API file handle, normalized from the SDK's
 * `types.File` (see gemini-client.ts's GeminiFileHandle / normalizeFileHandle). */
export interface FilesApiFileHandle {
  name: string;
  uri: string;
  mimeType: string;
  state: string;
  errorMessage?: string;
}

/** Injected Files API surface — lets callers (and tests) swap in a fake
 * without touching the real @google/genai client. Backed in production by
 * gemini-client.ts's uploadFileToFilesApi()/getFilesApiFile(). */
export interface FilesApiUploader {
  upload: (filePath: string, mimeType: string) => Promise<FilesApiFileHandle>;
  getStatus: (name: string) => Promise<FilesApiFileHandle>;
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/** Rethrows an already-structured error (has a `code` field, e.g.
 * `no_credentials` from getClient(), or `api_error`/`transient` from
 * gemini-client.ts's Files API wrappers) unchanged; wraps anything else as
 * an actionable `ocr_failed` mentioning "Files API" so the `/academic-writer:ocr`
 * skill's per-page-split fallback still recognizes and triggers on it. */
function wrapFilesApiError(err: unknown, filePath: string, verb: string): Error {
  if (err && typeof err === 'object' && 'code' in err) return err as unknown as Error;
  const message = err instanceof Error ? err.message : String(err);
  return ocrFailed(
    `Gemini Files API ${verb} failed for "${filePath}": ${message}. Retry, or fall back to ` +
      'per-page OCR (page_range narrowed to one page at a time).',
    { file: filePath },
  ) as unknown as Error;
}

/**
 * Upload a local file to the Gemini Files API and poll until it reaches
 * ACTIVE, for use when a batch's estimated inline payload exceeds
 * INLINE_SIZE_LIMIT_BYTES (see decideUploadPath above). Returns the file's
 * URI (+ mimeType) for use in a `fileData` content part in a subsequent
 * generateContent call — see buildOcrParts().
 *
 * PROCESSING is polled at FILES_API_POLL_INTERVAL_MS until either ACTIVE
 * (success), FAILED (throws an actionable ocr_failed error), or
 * FILES_API_POLL_TIMEOUT_MS elapses (throws an actionable timeout error).
 * Never proceeds silently past a non-ACTIVE terminal state.
 *
 * Caller (gemini_ocr.ts) is responsible for deleting the uploaded file after
 * use (success or failure) via the SDK's delete method — this function does
 * not delete, since the caller needs the file to still exist for the
 * subsequent generateContent call.
 */
export async function uploadViaFilesApi(
  filePath: string,
  mimeType: string,
  filesApi: FilesApiUploader,
  opts: { pollIntervalMs?: number; timeoutMs?: number } = {},
): Promise<UploadedFileRef> {
  const pollIntervalMs = opts.pollIntervalMs ?? FILES_API_POLL_INTERVAL_MS;
  const timeoutMs = opts.timeoutMs ?? FILES_API_POLL_TIMEOUT_MS;

  let handle: FilesApiFileHandle;
  try {
    handle = await filesApi.upload(filePath, mimeType);
  } catch (err) {
    throw wrapFilesApiError(err, filePath, 'upload');
  }

  const deadline = Date.now() + timeoutMs;
  while (handle.state === 'PROCESSING') {
    if (Date.now() >= deadline) {
      throw ocrFailed(
        `Gemini Files API upload of "${filePath}" was still PROCESSING after ` +
          `${Math.round(timeoutMs / 1000)}s and did not reach ACTIVE in time. The file may be ` +
          'unusually large or the service may be degraded — retry, or fall back to per-page ' +
          'OCR (page_range narrowed to one page at a time).',
        { file: filePath, name: handle.name, timeout_ms: timeoutMs },
      ) as unknown as Error;
    }
    // eslint-disable-next-line no-await-in-loop -- polling is inherently sequential
    await sleep(pollIntervalMs);
    try {
      // eslint-disable-next-line no-await-in-loop -- polling is inherently sequential
      handle = await filesApi.getStatus(handle.name);
    } catch (err) {
      throw wrapFilesApiError(err, filePath, 'status check');
    }
  }

  if (handle.state === 'FAILED') {
    throw ocrFailed(
      `Gemini Files API failed to process the uploaded file "${filePath}"` +
        `${handle.errorMessage ? `: ${handle.errorMessage}` : '.'} Retry, or fall back to ` +
        'per-page OCR (page_range narrowed to one page at a time).',
      { file: filePath, name: handle.name },
    ) as unknown as Error;
  }

  if (handle.state !== 'ACTIVE') {
    throw ocrFailed(
      `Gemini Files API returned an unexpected state "${handle.state}" for uploaded file ` +
        `"${filePath}". Retry, or fall back to per-page OCR (page_range narrowed to one page ` +
        'at a time).',
      { file: filePath, name: handle.name, state: handle.state },
    ) as unknown as Error;
  }

  return { name: handle.name, uri: handle.uri, mimeType: handle.mimeType || mimeType };
}

// ---------------------------------------------------------------------------
// media_resolution selection
// ---------------------------------------------------------------------------

export type MediaResolution = 'media_resolution_medium' | 'media_resolution_high';

/**
 * media_resolution_high costs more tokens per image but preserves more
 * detail for dense/small-font pages. We key this off response_format alone
 * (not a per-page density heuristic) for this staging pass: "detailed" is
 * exactly the mode where a caller wants layout/structure notes and
 * confidence flags, which requires the model to actually resolve fine
 * detail (footnotes, marginalia, small captions) — so tying resolution to
 * that same flag is a reasonable, simple proxy. A true per-page "dense or
 * small-font" heuristic would need either a first-pass cheap detection (out
 * of scope here) or metadata from detect_text_layer.py (e.g. font size
 * histogram) that isn't emitted yet.
 */
export function selectMediaResolution(responseFormat: 'concise' | 'detailed'): MediaResolution {
  return responseFormat === 'detailed' ? 'media_resolution_high' : 'media_resolution_medium';
}

// ---------------------------------------------------------------------------
// finishReason -> actionable StructuredError
// ---------------------------------------------------------------------------

/**
 * Map a Gemini finishReason to an actionable structured error, or null if
 * the call finished normally (STOP) and the caller should proceed to parse
 * the response. Never surfaces the raw code alone (Quality Bar #20).
 */
export function mapFinishReasonError(
  finishReason: string,
  pageNumber: number,
): StructuredError | null {
  switch (finishReason) {
    case 'STOP':
      return null;
    case 'MAX_TOKENS':
      return ocrFailed(
        `Gemini ran out of output tokens on page ${pageNumber} before finishing. ` +
          `Try response_format=concise (fewer fields per page) or a smaller page_range ` +
          `per call so each batch has more token headroom.`,
        { finish_reason: finishReason, page: pageNumber },
      );
    case 'SAFETY':
      return ocrFailed(
        `Gemini stopped early (safety filter) on page ${pageNumber}. Try response_format=concise, ` +
          `or isolate this page in its own page_range call to confirm whether it reproduces.`,
        { finish_reason: finishReason, page: pageNumber },
      );
    case 'RECITATION':
      return ocrFailed(
        `Gemini stopped early (recitation filter) on page ${pageNumber} — it flagged the ` +
          `content as matching known copyrighted text closely. Try a smaller page_range ` +
          `so this page is isolated, or reduce rasterization DPI.`,
        { finish_reason: finishReason, page: pageNumber },
      );
    default:
      return ocrFailed(
        `Gemini stopped early on page ${pageNumber} for an unexpected reason (${finishReason}). ` +
          `Try re-running with a smaller page_range.`,
        { finish_reason: finishReason, page: pageNumber },
      );
  }
}
